import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        opp_last = history[-1][1]
        return 'D' if opp_last == 'D' else 'C'

    last_opp = history[-1][1]
    prev_opp = history[-2][1]
    last_own = history[-1][0]

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1
    opp_coop_rate = (n - opp_def) / float(n)

    recent_len = 8 if n >= 8 else n
    recent_def = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_def += 1

    if n >= 6 and opp_def >= n // 2 + 1:
        return 'D'

    if opp_coop_rate > 0.9 and recent_def == 0:
        if n >= 96:
            return 'D'
        return 'C'

    if last_opp == 'D' and prev_opp == 'D':
        if n < 10:
            return 'D'
        if recent_def >= 3:
            return 'D'
        if rng.random() < 0.45:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_own == 'D':
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        return 'D'

    if last_opp == 'C' and prev_opp == 'C':
        if n > 96:
            return 'D'
        return 'C'

    if last_opp == 'C':
        if recent_def == 0 and opp_coop_rate > 0.75:
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    return 'C'
